import "server-only";

import { catalog } from "@/lib/catalog";
import type { Title } from "@/lib/types";

/**
 * Catalog reads.
 *
 * The snapshot in `catalog.data.json` is the catalogue — complete, already
 * AniList-sourced, and regenerated by `npm run catalog`. Nothing here calls
 * AniList at request time: enriching a catalogue this size live would be 16+
 * GraphQL requests per cache miss against a 30 req/min public limit, which
 * rate-limits the app into its own fallback path. Refreshing metadata is a
 * build step, not a page load.
 */

const byId = new Map(catalog.map((title) => [title.id, title]));
/** Catalog position = AniList popularity rank; used as a search tiebreaker. */
const rankById = new Map(catalog.map((title, index) => [title.id, index]));

/**
 * Strip the fields a poster card never reads.
 *
 * Grids and rails are client components, so every Title they receive is
 * serialized into the RSC payload — and a full Title now carries its whole
 * episode list. /series alone renders 650+ of them, which is megabytes of
 * episode data the page never displays. Detail pages still use `getCatalogTitle`
 * for the complete record.
 */
export function toListTitle(title: Title): Title {
  return {
    id: title.id,
    title: title.title,
    year: title.year,
    genres: title.genres,
    score: title.score,
    poster: title.poster,
    banner: title.banner,
    logo: title.logo,
    color: title.color,
    format: title.format,
  };
}

export function getCatalog(): Promise<Title[]> {
  return Promise.resolve(catalog);
}

export async function getCatalogTitle(id: string): Promise<Title | undefined> {
  if (!/^[1-9]\d*$/.test(id)) return undefined;
  return byId.get(id);
}

/** Same id -> Title lookup `getCatalogTitle` uses, for callers that need the whole map (e.g. reco). */
export function getCatalogIndex(): Map<string, Title> {
  return byId;
}

export async function getTitlesByFormat(
  format: "tv" | "movie"
): Promise<Title[]> {
  return catalog.filter((title) => title.format === format).map(toListTitle);
}

export async function getFeaturedTitle(): Promise<Title> {
  return catalog.find((title) => title.banner) ?? catalog[0];
}

function normalize(value: string): string {
  return value
    .normalize("NFKD")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim()
    .toLocaleLowerCase();
}

/**
 * Catalog search over title, season titles and genres.
 *
 * Ranked so exact and prefix matches beat incidental substring hits — typing
 * "one" should surface ONE PIECE and One-Punch Man before "Alone in a
 * Wonderland". Season titles are searchable too, so "Shippuden" finds Naruto.
 */
export async function searchCatalog(query: string, limit = 60): Promise<Title[]> {
  const needle = normalize(query);
  if (needle.length === 0) return [];

  const scored: Array<{ title: Title; rank: number }> = [];
  for (const title of catalog) {
    const name = normalize(title.title);
    let rank = -1;

    if (name === needle) rank = 0;
    else if (name.startsWith(needle)) rank = 1;
    else if (name.includes(needle)) rank = 2;
    else if ((title.seasons ?? []).some((s) => normalize(s.title).includes(needle))) rank = 3;
    else if (title.genres.some((genre) => normalize(genre) === needle)) rank = 4;

    if (rank >= 0) scored.push({ title, rank });
  }

  return scored
    // Catalog order is AniList popularity, so it is the natural tiebreaker.
    .sort(
      (a, b) =>
        a.rank - b.rank ||
        (rankById.get(a.title.id) ?? 0) - (rankById.get(b.title.id) ?? 0)
    )
    .slice(0, limit)
    .map((entry) => toListTitle(entry.title));
}
